            "title": "المادة 41",
            "content": "1 - يتألف العنوان التجاري من اسم التاجر ولقبه .\n2 - يجب ان يختلف العنوان بوضوح عن العناوين المسجلة قبلا .\n3 - للتاجر ان يضيف ما يشاء الى عنوانه التجاري بشرط ان لا تحمل هذه الاضافة الغير على فهم خاطىء فيما يتعلق بهويته او باهمية تجارية وسمعتها او بوضعه المالي او بوجود شركة او بنوعها ."
