            "content": "1 - الساحب ضامن قبول سند السحب ووفاءه ، وله ان يشترط الاعفاء من ضمان القبول .\n2 - اما ضمان الوفاء فكل شرط للاعفاء منه يعتبر كأن لم يكن ."
