            "article_num": "146",
            "title": "المادة 146",
            "content": "1 - يعبتر من بيده السند انه حامله الشرعي متى اثبت انه صاحب الحق فيه بتظهيرات متصلة بعضها ببعض ولو كان اخرها تظهيرا على بياض .\n2 - والتظهيرات المشطوبة تعتبر في هذا الشأن كأن لم تكن .\n3 - واذا اعقب التظهير على بياض تظهير اخر، اعتبر الموقع على التظهير الاخير انه هو الذي آل اليه الحق في السند بذلك التظهير على بياض .\n4 - واذا زالت يد شخص عن السند بحادث ما فحامله متى اثبت انه هو صاحب الحق فيه وفقاَ للفقرة السابقة لا يلزم برده الا اذا كان قد حصل عليه بنية سيئة او خطأ جسيم ."
