            "content": "1 - يجوز لكل شخص ان يطلب اعطاءه نسخة عن القيود المدرجة في السجل مقابل رسم يحدد في الانظمة المرعية .\n2 - لمراقب السجل عند الاقتضاء ان يعطي شهادة بعدم وجود قيود .\n3 - ويصدق مراقب السجل على مطابقة النسخ للاصل ."
